:root {
	--ink: #0000cc;
	--line: #424242;
	--line-vertical: #f7f9fc !important;
	--line-horizontal: #adadad !important;
	--header-font-size-portrait: 12pt !important;
	--header-font-size-landscape: 12pt !important;
	--column-header-font-size-portrait: 10px !important;
	--column-header-font-size-landscape: 10px !important;
	--items-font-size-portrait: 8pt !important;
	--items-font-size-landscape: 9pt !important;
}

/* Common styles */
.print-format {
	padding: 0.2in !important;
}

.print-format .row:not(.section-break) {
	margin-top: unset !important;
}

.print-format p {
	line-height: 1.6 !important;
}

.print-format th {
	vertical-align: middle !important;
	padding: 4px !important;
}

.print-format td {
	padding: 2px !important;
}

.label {
	font-size: unset !important;
}

/* Temp wrapper for standalone preview - A4 Landscape
      .temp-wrapper {
        width: 297mm;
        min-height: 210mm;
        margin: 10mm auto;
        padding: 5mm;
        background: #fff;
        border: 1px dashed #999;
      }
      */

.page {
	/* No need width and height in real Print Format, it will be set by the browser */
	/* width: 297mm;
        height: 210mm;
        */
	display: flex;
	flex-direction: column;
	justify-content: space-between;
}
.section-header {
	min-height: 50mm;
	width: 100%;
	display: flex;
	flex-direction: column;
}
.logo {
	max-width: 50px !important;
}
.company-name {
	font-weight: bold;
}
.company-address-contact {
	display: flex;
	flex-direction: column;
	container-type: inline-size;
	width: 100%;
}
#total__label {
	font-weight: 600;
}
/* 2. Situation 1: A4 Portrait (Width is narrower than height) */
@media screen and (orientation: portrait), print and (orientation: portrait) {
    .print-format p {
	margin: 3px 0px 5px 0px !important;
}
	.company-name {
		font-size: var(--header-font-size-portrait);
	}
	.company-address,
	.company-contact {
		font-size: var(--items-font-size-portrait); /* 8pt Optimized for narrow 210mm layout */
	}
	.doc-meta .row {
        font-size: var(--items-font-size-portrait)
    }
    .doc-meta .label {
	width: 70px;
}
	.items-wrap {
		height: 760px;
	}
	.items-bg {
		height: 719px;
		position: relative;
	}
	.items-data {
		position: absolute;
		top: 50px;
		font-size: var(--items-font-size-portrait);
		width: 100%;
	}
	.items-data p span {
		display: inline-flex;
		overflow: overlay;
	}
	#item__code {
		width: 65px;
	}
	#item__name {
		width: 148px;
	}
	#warehouse__from_branch {
		width: 38px;
	}
	#warehouse__from_dept {
		width: 38px;
	}
	#warehouse__from {
		width: 38px;
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
	#warehouse__from_location {
		width: 38px;
	}
	#warehouse__to_branch {
		width: 38px;
	}
	#warehouse__to_dept {
		width: 38px;
	}
	#warehouse__to {
		width: 38px;
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
	#warehouse__to_location {
		width: 38px;
	}
	#item__qty {
		width: 45px;
		align-items: center;
		justify-content: center;
	}
	#item__cost {
		width: 60px;
	}
	#item__value {
		width: 50px;
	}
	#item__uom {
		width: 38px;
	}
	#total__row {
		display: flex;
		justify-content: space-between;
		align-items: center;
		width: 100%;
	}
	#total__label {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		margin-left: auto;
		width: 30%;
	}
	#total__group {
		display: flex;
		width: 70%;
	}
	#total__wh {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		width: 50%;
	}
	#total__qty {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		width: 20%;
	}
	#total__cost {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		width: 12%;
	}
	#total__value {
		display: flex;
		align-items: center;
		padding-left: 15px;
		width: 15%;
	}
	.info {
		font-size: var(--items-font-size-portrait);
	}
	.sig {
		font-size: var(--items-font-size-portrait);
	}
	.sig .date {
		font-size: var(--items-font-size-portrait);
	}
	table.items {
		font-size: var(--column-header-font-size-portrait);
	}
	.items-total-footer {
		font-size: var(--items-font-size-portrait);
	}
}

/* 3. Situation 2: A4 Landscape (Width is wider than height) */
@media screen and (orientation: landscape), print and (orientation: landscape) {
    .print-format p {
	margin: 3px 0px 3px !important;
}
	.company-name {
		font-size: var(--header-font-size-landscape);
	}
	.company-address,
	.company-contact {
		font-size: var(
			--items-font-size-landscape
		); /* 9pt Larger text allowed for wide 297mm layout */
	}
	.doc-meta .row {
        font-size: var(--items-font-size-landscape)
    }
    .doc-meta .label {
	width: 85px;
}
	.items-wrap {
		height: 426px;
	}
	.items-bg {
		height: 419px;
		position: relative;
	}
	.items-data {
		position: absolute;
		top: 50px;
		font-size: var(--items-font-size-portrait);
		width: 100%;
	}
	.items-data p span {
		display: inline-flex;
		overflow: overlay;
	}
	#item__code {
		width: 95px;
	}
	#item__name {
		width: 220px;
	}
	#warehouse__from_branch {
		width: 58px;
	}
	#warehouse__from_dept {
		width: 50px;
	}
	#warehouse__from {
		width: 55px;
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
	#warehouse__from_location {
		width: 50px;
	}
	#warehouse__to_branch {
		width: 55px;
	}
	#warehouse__to_dept {
		width: 55px;
	}
	#warehouse__to {
		width: 58px;
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
	#warehouse__to_location {
		width: 52px;
	}
	#item__qty {
		width: 75px;
		align-items: center;
		justify-content: center;
	}
	#item__cost {
		width: 82px;
	}
	#item__value {
		width: 70px;
	}
	#item__uom {
		width: 52px;
	}
	#total__row {
		display: flex;
		justify-content: space-between;
		align-items: center;
		width: 100%;
	}
	#total__label {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		margin-left: auto;
		width: 30%;
	}
	#total__group {
		display: flex;
		width: 70%;
	}
	#total__wh {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		width: 50%;
	}
	#total__qty {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		width: 18%;
	}
	#total__cost {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		width: 13%;
	}
	#total__value {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		width: 10%;
	}
	.info {
	    font-size: var(--items-font-size-landscape);
	}
	.sig {
		font-size: var(--items-font-size-landscape);
	}
	.sig .date {
		font-size: var(--items-font-size-landscape);
	}
	table.items {
		font-size: var(--column-header-font-size-landscape);
	}
	.items-total-footer {
		font-size: var(--items-font-size-landscape);
	}
}
/* Header sub-section */
.a4-header-container {
	width: 100%;
	display: grid;
	grid-template-columns: repeat(12, 1fr);
	flex: 1;
	justify-content: space-between;
	align-items: center;
	width: 100%;
	box-sizing: border-box;
	height: 100%;
}
.header-left {
	display: flex;
	flex: 1;
	justify-content: flex-start;
	align-items: flex-start;
	grid-column: span 3;
	height: 100%;
}
.header-center {
	display: flex;
	flex-direction: column;
	align-items: center;
	text-align: center;
	grid-column: span 6;
	height: 100%;
}
.company-info {
	width: 100%;
}
.header-right {
	display: flex;
	flex: 1;
	justify-content: flex-end;
	align-items: flex-end;
	grid-column: span 3;
	height: 100%;
}
.doc-title {
	margin-top: 8px;
	font-size: 16px;
	font-weight: bold;
}
/* Info sub-section */
.info {
	width: 100%;
	display: flex;
	margin-top: 2px;
	border: 1px solid var(--line);
	border-radius: 8px;
	height: fit-content;
}
.info .col {
	flex: 1;
	padding: 6px 8px;
	border-right: 1px solid var(--line);
}
.info .col:last-child {
	border-right: none;
}
.info .line {
	display: flex;
	margin: 3px 0;
}
.info .k {
	width: 90px;
	font-weight: bold;
	flex-shrink: 0;
}
.info .code {
	width: 90px;
	flex-shrink: 0;
}
/* Doc-meta sub-section */
.doc-meta {
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	width: 100%;
	border: 1px solid var(--line);
	border-radius: 8px;
	height: fit-content;
	container-type: inline-size;
}
.doc-meta .row {
	display: flex;
	border-bottom: 1px solid var(--line);
	width: 100%;
	align-items: center;
	white-space: normal;
}
.doc-meta .row:last-child {
	border-bottom: none;
}
.doc-meta .label {
	font-weight: bold;
	padding: 4px 6px;
}
.doc-meta .value {
	padding: 4px 6px;
	text-align: left;
	border-left: 1px solid var(--line);
}
.section-content {
	flex: 1;
	height: 100%;
}
.section-footer {
	position: absolute;
	bottom: 0.2in;
	left: 0.2in;
	right: 0.2in;
	width: calc(100% - 0.4in);
	align-items: center;
}

/* Signatures */
.signatures {
	display: flex;
	border: 1px solid var(--line);
	border-radius: 8px;
	height: 100%;
}
.sig {
	display: flex;
	flex-direction: column;
	justify-content: flex-end;
	flex: 1;
	padding: 26px 6px 12px;
	text-align: center;
	border-right: 1px solid var(--line);
}
.sig:last-child {
	border-right: none;
}
.sig .line {
	border-top: 1px dotted var(--ink);
	margin-top: 10mm;
}
.sig .role {
	margin-bottom: 6px;
}
.sig .date {
	display: flex;
	justify-content: center;
	align-items: flex-end;
	width: 100%;
}

/* Item table */
/* Wrapper owns the rounded outer border; overflow clips the table's
     square corners so they follow the curve. */
.items-wrap {
	position: relative;
	display: flex;
	flex-direction: column;
	margin-top: 0.5mm;
	border-style: solid !important;
	border-color: var(--line) !important;
	border-width: 1px !important;
	border-radius: 8px;
	overflow: hidden;
}
table.items {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}
/* Grid lines via border */
table.items th,
table.items td {
	border-right-style: solid !important;
	border-right-color: var(--line) !important;
	border-bottom-style: dotted !important;
	border-bottom-color: var(--line-horizontal) !important;
	border-width: 1px !important;
	padding: 4px 5px;
	text-align: center;
	box-sizing: border-box;
	text-overflow: ellipsis;
	overflow: hidden;
	white-space: nowrap;
}
/* Drop the cells that sit on the outer edge so their square border
     doesn't double up over the wrapper's rounded border. */
table.items tr th:first-child,
table.items tr td:first-child {
	border-left: none;
}
table.items tr th:last-child,
table.items tr td:last-child {
	border-right: none;
}
table.items thead tr:first-child th {
	border-top: none;
}
table.items tfoot tr:last-child td {
	border-bottom: none;
}

table.items thead th {
	border-bottom-style: solid !important;
	border-bottom-color: var(--line) !important;
	border-bottom-width: 1px !important;
	font-weight: bold;
	text-align: center;
}

/* Phase 2 Render Data*/
/* 2. THE FIX: Neutralize the incoming DB Data Row cells */
table.items tbody tr.data td {
	/* Remove the default cell-by-cell borders so they don't draw double lines */
	border-right: none !important;

	/* Keep only a subtle bottom dotted divider if you want separate rows */
	border-bottom: 1px dotted var(--line-horizontal) !important;

	/* Ensure padding and content alignment match the structural layer exactly */
	padding: 8px 4px;
	box-sizing: border-box;
}

/* Finished */

/* Column widths */
.items .col-code {
	width: 10%;
}
.items .col-name {
	width: 20%;
}
.items .col-narrow {
	width: 5.5%;
}
.items .col-qty {
	width: 7%;
}
.items .col-cost {
	width: 8%;
}
.items .col-value {
	width: 7%;
}
.items .col-unit {
	width: 6%;
}

/* Finished Column widths*/

.items td.text-left {
	text-align: left;
}

.items td.text-right {
	text-align: right;
}

/* Spacer row for empty vertical space */
.items tbody td {
	height: auto;
	padding: 3px 5px;
	vertical-align: top;
	box-sizing: border-box;
}

.items tbody td.data {
	height: auto;
}

.items .data td {
	height: auto;
	border-bottom: 1px solid transparent;
}

.items tfoot td {
	height: auto;
	font-weight: bold;
}
/* Enterprise Table Solution */

/* All cells have border-right by default from general border style */
/* Only the absolute last column (หน่วยนับ) removes border-right */
/* Only remove border from the very last column (หน่วยนับ) */
table.items th.col-unit,
table.items td.col-unit {
	border-right: none !important;
}

/* Fixed row heights */
.items tbody tr {
	height: 20px;
}

/* Enterprise Footer - outside table */
.items-total-footer {
	margin-top: auto;
	display: flex;
	width: 100%;
	height: 36px;
	border-top: 1px solid var(--line);
	/*
        border-left: 1px solid var(--line);
        border-right: 1px solid var(--line);
        border-bottom: 1px solid var(--line);
        */
	box-sizing: border-box;
}

.items-total-footer > div {
	display: flex;
	align-items: center;
	padding: 0 5px;
	border-right: 1px solid var(--line);
	box-sizing: border-box;
	height: 100%;
}

.items-total-footer > div:last-child {
	border-right: none;
}

.items-total-footer .total-label {
	width: 10%;
	font-weight: bold;
	text-align: right;
	padding-right: 10px;
}

.items-total-footer .total-empty {
	width: 5.5%;
}

.items-total-footer .total-narrow {
	width: 5.5%;
}

.items-total-footer .total-qty {
	width: 7%;
	justify-content: flex-end;
}

.items-total-footer .total-cost {
	width: 8%;
}

.items-total-footer .total-value {
	width: 7%;
	font-weight: bold;
	justify-content: flex-end;
}

.items-total-footer .total-unit {
	width: 6%;
}
